#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: server, DNS, deploy pipeline, site on Vercel, Search Console, live checks.
# ──────────────────────────────────────────────────────────────────────────

run_wizard() {

ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
ENV_FILE="${ENV_FILE:-$ROOT/docs/deploy/.env}"
cd "$ROOT"
API_REPO="austial/api.austial.com"
SITE_REPO="austial/services.austial.com"
KEY="$HOME/.ssh/austial_deploy"
SSH_OPTS=(-o StrictHostKeyChecking=accept-new -o ConnectTimeout=15)

TOTAL_STAGES=10

banner "Austial: server, deploy pipeline, site and launch checks"

# ── 1. Preflight ──────────────────────────────────────────────────────────
stage "Preflight"
say "Run scripts/setup-services.sh first: it creates $ENV_FILE (SES, Google, database)."
if [[ ! -f "$ENV_FILE" ]]; then
  warn "$ENV_FILE does not exist yet."
  confirm "Continue anyway? (the server will have no .env until you finish that wizard)" || exit 1
fi
for tool in ssh scp ssh-keygen gh curl dig; do
  command -v "$tool" >/dev/null 2>&1 || warn "missing tool: $tool"
done
gh auth status >/dev/null 2>&1 || { warn "gh is not signed in: run 'gh auth login' as an account with admin on $API_REPO."; exit 1; }
if [[ "$(gh repo view "$API_REPO" --json viewerPermission -q .viewerPermission 2>/dev/null)" != "ADMIN" ]]; then
  warn "Your gh account is not an admin of $API_REPO, so setting secrets will fail."
  note "Add yourself as admin, or sign in as the account that owns it."
fi
say "Domain: you need to be able to add DNS records for austial.com wherever it is managed."
pause

# ── 2. Deploy key ─────────────────────────────────────────────────────────
stage "A dedicated SSH key for deploys"
if [[ -f "$KEY" ]]; then
  note "$KEY already exists, reusing it."
else
  ssh-keygen -t ed25519 -N "" -C "austial-github-deploy" -f "$KEY" >/dev/null
  say "Created $KEY (private, stays on this machine and in the GitHub secret) and $KEY.pub."
fi
say "Public key:"
printf '\n    %s\n\n' "$(cat "$KEY.pub")"
pause

# ── 3. Droplet ────────────────────────────────────────────────────────────
stage "DigitalOcean Droplet"
say "The server that runs the API and Caddy."
open_url "https://cloud.digitalocean.com/droplets/new"
step "Region: the same one as your Postgres cluster (so the database is on the private network)."
step "Image: Ubuntu 24.04 LTS. Size: Basic, Regular SSD, 1 vCPU / 2 GB is plenty."
step "Authentication: SSH key → add YOUR usual public key (not the deploy key above). Name it austial-api."
step "Create, then copy the Droplet's IPv4 address."
ask DROPLET_IP "Droplet IPv4 address:"
ask ROOT_USER "SSH user for first login (Enter for root):"
ROOT_USER="${ROOT_USER:-root}"
step "If you use a managed database: open it → Settings → Trusted sources → add this Droplet."
pause "Press Enter when the Droplet is up and (if used) trusted by the database..."

# ── 4. Bootstrap the server ───────────────────────────────────────────────
stage "Set up the server"
say "This logs in as $ROOT_USER@$DROPLET_IP and:"
note "  installs Docker, creates a 'deploy' user, opens only ports 22, 80 and 443,"
note "  creates /opt/api, and copies in the compose file, Caddyfile and your .env (mode 600)."
if confirm "Run the setup on $DROPLET_IP now?"; then
  ssh "${SSH_OPTS[@]}" "$ROOT_USER@$DROPLET_IP" 'bash -s' <<REMOTE
set -euo pipefail
export DEBIAN_FRONTEND=noninteractive
command -v docker >/dev/null || curl -fsSL https://get.docker.com | sh
id deploy >/dev/null 2>&1 || useradd -m -s /bin/bash deploy
usermod -aG docker deploy
install -d -m 700 -o deploy -g deploy /home/deploy/.ssh
echo '$(cat "$KEY.pub")' > /home/deploy/.ssh/authorized_keys
chown deploy:deploy /home/deploy/.ssh/authorized_keys && chmod 600 /home/deploy/.ssh/authorized_keys
install -d -m 755 -o deploy -g deploy /opt/api
apt-get install -y -qq ufw >/dev/null
ufw allow 22/tcp >/dev/null && ufw allow 80/tcp >/dev/null && ufw allow 443/tcp >/dev/null
ufw --force enable >/dev/null
echo "server ready"
REMOTE
  scp "${SSH_OPTS[@]}" "$ROOT/docs/deploy/docker-compose.yml" "$ROOT/docs/deploy/Caddyfile" "$ROOT_USER@$DROPLET_IP:/opt/api/"
  if [[ -f "$ENV_FILE" ]]; then
    scp "${SSH_OPTS[@]}" "$ENV_FILE" "$ROOT_USER@$DROPLET_IP:/opt/api/.env"
  fi
  ssh "${SSH_OPTS[@]}" "$ROOT_USER@$DROPLET_IP" "chown deploy:deploy /opt/api/* /opt/api/.env 2>/dev/null; chmod 600 /opt/api/.env 2>/dev/null; ls -la /opt/api"
  if ssh "${SSH_OPTS[@]}" -i "$KEY" -o IdentitiesOnly=yes "deploy@$DROPLET_IP" 'docker ps >/dev/null && echo deploy-user-ok'; then
    say "The deploy key can log in and use Docker."
  else
    warn "The deploy key could not log in as 'deploy'. Re-run this stage."
  fi
else
  SKIPPED+=("Server setup on $DROPLET_IP (re-run scripts/setup-deploy.sh)")
fi
pause

# ── 5. DNS for the API ────────────────────────────────────────────────────
stage "DNS: api.austial.com"
say "In the DNS panel for austial.com add:"
step "Type A   Name: api   Value: $DROPLET_IP   (TTL 300 or Auto)"
say "Waiting for it to resolve (Ctrl-C to skip, you can re-run later)..."
for _ in $(seq 1 40); do
  [[ "$(dig +short api.austial.com 2>/dev/null | tail -n1)" == "$DROPLET_IP" ]] && { say "api.austial.com → $DROPLET_IP"; break; }
  sleep 6
done
pause

# ── 6. GitHub secrets ─────────────────────────────────────────────────────
stage "GitHub: secrets and environment"
say "The pipeline needs four secrets on $API_REPO, plus a 'production' environment."
gh api -X PUT "repos/$API_REPO/environments/production" >/dev/null 2>&1 && say "Environment 'production' is ready." || warn "Could not create the 'production' environment."
set_secret DEPLOY_HOST "$DROPLET_IP"
set_secret DEPLOY_USER "deploy"
if gh secret set DEPLOY_SSH_KEY --repo "$API_REPO" < "$KEY" >/dev/null 2>&1; then
  WRITTEN_SECRET+=("DEPLOY_SSH_KEY"); say "✓ set GitHub secret DEPLOY_SSH_KEY"
else
  SKIPPED+=("GitHub secret DEPLOY_SSH_KEY (gh secret set DEPLOY_SSH_KEY < $KEY)")
fi
say "Now a token so the server can pull the private image."
open_url "https://github.com/settings/tokens/new?scopes=read:packages&description=austial-ghcr-pull"
step "Expiration: 1 year (or no expiry). Scope read:packages is pre-ticked. Generate token, copy it."
warn "Create it on the SAME GitHub account that triggers deploys (the workflow logs in as that user)."
ask_secret GHCR_PULL_TOKEN "Paste the token (hidden):"
set_secret GHCR_PULL_TOKEN "$GHCR_PULL_TOKEN"
pause

# ── 7. Run the pipeline ───────────────────────────────────────────────────
stage "Deploy"
if confirm "Start the Test, build and deploy workflow now?"; then
  gh workflow run "Test, build and deploy" --repo "$API_REPO" --ref main
  sleep 6
  RUN_ID="$(gh run list --repo "$API_REPO" --workflow "Test, build and deploy" --limit 1 --json databaseId -q '.[0].databaseId')"
  gh run watch "$RUN_ID" --repo "$API_REPO" --exit-status || warn "The workflow failed. Open it: gh run view $RUN_ID --repo $API_REPO --log-failed"
  say "Checking https://api.austial.com/healthz (Caddy needs a minute to get its certificate)..."
  for _ in $(seq 1 30); do
    code="$(curl -s -o /dev/null -w '%{http_code}' https://api.austial.com/healthz 2>/dev/null || true)"
    [[ "$code" == "200" ]] && { say "✓ API is live: https://api.austial.com/healthz returned 200"; break; }
    sleep 6
  done
  [[ "${code:-}" == "200" ]] || warn "No 200 yet. On the server: cd /opt/api && docker compose logs --tail 50"
else
  SKIPPED+=("Run the deploy workflow: gh workflow run 'Test, build and deploy' --repo $API_REPO")
fi
pause

# ── 8. Vercel ─────────────────────────────────────────────────────────────
stage "Vercel: the website"
open_url "https://vercel.com/new"
step "Import $SITE_REPO (install the Vercel GitHub app for the austial account if asked)."
step "Framework: Next.js (auto). Before deploying add Environment Variables:"
note "    NEXT_PUBLIC_API_URL = https://api.austial.com"
note "    NEXT_PUBLIC_SITE_URL = https://services.austial.com"
step "Deploy. Then project → Settings → Domains → add services.austial.com."
step "In your DNS add the record Vercel shows (usually CNAME  services → cname.vercel-dns.com)."
step "Project → Analytics → Enable Web Analytics."
say "Waiting for the site (Ctrl-C to skip)..."
for _ in $(seq 1 40); do
  code="$(curl -s -o /dev/null -w '%{http_code}' https://services.austial.com/ 2>/dev/null || true)"
  [[ "$code" == "200" ]] && { say "✓ https://services.austial.com returned 200"; break; }
  sleep 6
done
pause

# ── 9. Search Console ─────────────────────────────────────────────────────
stage "Google Search Console"
open_url "https://search.google.com/search-console/welcome"
step "Choose 'URL prefix' → https://services.austial.com → Continue (or a Domain property for austial.com)."
step "Verify with the method offered (the DNS TXT record is easiest if you chose Domain)."
step "Left menu → Sitemaps → add  sitemap.xml → Submit."
step "URL Inspection → paste https://services.austial.com/ → Request indexing."
pause

# ── 10. Production checks ─────────────────────────────────────────────────
stage "Check the live flow"
say "I'll open the booking page. Work through these with a real inbox and tick each."
open_url "https://services.austial.com/book"
PASS=0; TOTAL=6
checks=(
  "Book a slot: the 6-digit code email arrives, entering it confirms, a Google Calendar event with a Meet link appears, and the confirmation and notify emails arrive"
  "Use the link in the confirmation to reschedule, then cancel: the calendar event follows both"
  "A slot about 24.5 hours away gets its reminder email within the hour"
  "Send a brief at /brief: the notify email arrives"
  "A time marked busy in your Google Calendar is missing from the slot list"
  "Repeating hold requests quickly returns 'too many requests' instead of letting them through"
)
for c in "${checks[@]}"; do
  if confirm "$c. Did it work?"; then PASS=$((PASS+1)); else SKIPPED+=("Failed live check: $c"); fi
done
if [[ -n "$(_existing ADMIN_TOKEN || true)" ]]; then
  say "Latest leads, as seen through the admin route:"
  curl -s -H "Authorization: Bearer $(_existing ADMIN_TOKEN)" https://api.austial.com/v1/admin/leads | head -c 600; echo
fi
say "$PASS of $TOTAL live checks passed."
if command -v npx >/dev/null 2>&1 && confirm "Run Lighthouse (mobile) against the live site?"; then
  npx -y lighthouse@12 https://services.austial.com/ --quiet --only-categories=performance,accessibility,best-practices,seo \
    --chrome-flags="--headless=new" --output=json --output-path=/tmp/austial-lh.json >/dev/null 2>&1 \
    && node -e "const r=require('/tmp/austial-lh.json');console.log('  '+Object.values(r.categories).map(c=>c.id+': '+Math.round(c.score*100)).join('   '))" \
    || warn "Lighthouse could not run."
fi

finish
}

run_wizard "$@"; exit
